<?php
/** php tests/eligibility.php — creates ONLY a disposable sis_eligibility_test database. */
declare(strict_types=1);
if (PHP_SAPI !== 'cli') exit;
require __DIR__ . '/../app/bootstrap.php';
$cfg = sis_config(); $live = $cfg['db_name'];
$name = getenv('SIS_ELIGIBILITY_TEST_DB') ?: 'sis_eligibility_test';
if ($name === $live || !preg_match('/^sis_[a-z0-9_]*test$/', $name)) exit("Refusing an unsafe test database name.\n");
$server = new PDO(sprintf('mysql:host=%s;port=%d;charset=utf8mb4', $cfg['db_host'], $cfg['db_port']), $cfg['db_user'], $cfg['db_pass']);
$server->exec("DROP DATABASE IF EXISTS `$name`"); $server->exec("CREATE DATABASE `$name` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");
$cfg['db_name'] = $name; Db::connect($cfg);
foreach ([dirname(SIS_ROOT) . '/api/install.sql', SIS_ROOT . '/database/schema.sql', SIS_ROOT . '/database/seed.sql', SIS_ROOT . '/database/seed_accounting.sql'] as $file) {
    $sql = preg_replace('/^\s*--.*$/m', '', file_get_contents($file));
    foreach (array_filter(array_map('trim', explode(";\n", $sql))) as $statement) Db::q($statement);
}
require __DIR__ . '/_legacy-payments.php'; // v56: these flows predate the payment-plan rule
$failures = 0; $passed = 0;
function expect(bool $ok, string $message): void { if (!$ok) throw new RuntimeException($message); }
function rejects(callable $fn, string $contains): void { try { $fn(); } catch (AppError|Forbidden $e) { expect(stripos($e->getMessage(), $contains) !== false, 'Unexpected rejection: ' . $e->getMessage()); return; } throw new RuntimeException('Expected rejection: ' . $contains); }
function scenario(string $label, callable $fn): void { global $failures, $passed; try { $fn(); $passed++; echo "PASS $label\n"; } catch (Throwable $e) { $failures++; echo "FAIL $label: " . $e->getMessage() . "\n"; } }
function admin(): void { Auth::actAs((int) Db::val("SELECT id FROM sis_users WHERE username = 'admin'")); }
function policy(array $settings): void { admin(); Settings::save(array_replace(Settings::all(), $settings)); }
admin();
$registrar = Db::insert('sis_users', ['username'=>'elig_registrar','full_name'=>'Eligibility Registrar','role'=>'REGISTRAR','password_hash'=>password_hash('Testing12345', PASSWORD_DEFAULT)]);
$admissionUser = Db::insert('sis_users', ['username'=>'elig_admission','full_name'=>'Eligibility Admission','role'=>'ADMISSION','password_hash'=>password_hash('Testing12345', PASSWORD_DEFAULT)]);
$section = GS::saveSection(null, '2026-2027', '1st Year', 'ELIG 1A');
$pre = GS::saveSubject(null, 'E101', 'Foundation', '3');
$dependent = GS::saveSubject(null, 'E201', 'Advanced', '3');
$third = GS::saveSubject(null, 'E301', 'Third Level', '3');
GS::saveCurriculum('ELIG', '1st Year', '1st Semester', [$pre]);
$category = Assessment::saveCategory(null, ['name'=>'Eligibility tuition','is_active'=>1]);
$label = Assessment::saveLabel(null, ['name'=>'Eligibility fee','category_id'=>$category,'charge_type'=>'FIXED','default_amount'=>'1000','is_active'=>1]);
$fee = Assessment::saveName(null,['name'=>'Eligibility assessment','is_active'=>1]); Assessment::setItem($fee,$label,'FIXED',100000);
function student(string $name): array { global $section; admin(); $id = GS::saveStudent(null,['studentName'=>$name,'sectionId'=>$section]);return GS::get('students',$id); }
function checkStudent(array $s, string $term='1st Semester', array $subjects=[], ?int $rid=null, ?string $override=null): array { return EnrollmentEligibility::check($s['id'],$s['studentId'],'2026-2027',$term,$subjects,$rid,null,$override); }
function tag(array $s, string $sy, string $term, array $subjects=[], array $pending=[]): void {
    $data=['studentId'=>$s['id'],'schoolYear'=>$sy,'term'=>$term,'subjects'=>$subjects,'pending'=>$pending,'incomplete'=>(bool)$pending || (bool)array_filter($subjects,fn($x)=>($x['mark']??'')==='INC')];
    Db::q('INSERT INTO docs(col,id,data) VALUES(?,?,?) ON DUPLICATE KEY UPDATE data=VALUES(data)', ['gradeCompletions',$s['id'].'__'.$sy.'__'.GS::termKey($term),json_encode($data)]);
}
scenario('new student eligible; documents explicitly not certified', function(){ $s=student('Eligible, New');$r=checkStudent($s);expect($r['can_confirm'],'New student blocked');expect(array_values(array_filter($r['checks'],fn($c)=>$c['code']==='documents'))[0]['state']==='INFO','Documents falsely cleared'); });
scenario('unknown identity blocked',function(){ $r=EnrollmentEligibility::check('missing','999','2026-2027','1st Semester');expect(!$r['can_confirm'],'Unknown student allowed'); });
scenario('duplicate registration cannot be overridden',function()use($section,$fee,$pre){$s=student('Duplicate, Check');[$id]=Registration::create(null,$s['studentId'],$section,'1st Semester',$fee,[$pre]);$r=checkStudent($s,'1st Semester',[$pre],null,'Admin reason');expect(!$r['can_create'],'Duplicate bypassed');rejects(fn()=>Registration::create(null,$s['studentId'],$section,'1st Semester',$fee,[$pre],[],'Admin reason'),'already registered');expect(checkStudent($s,'1st Semester',[$pre],$id)['can_confirm'],'Self registration treated as duplicate');});
scenario('document hold is term-scoped, blocks admin, and can be released',function(){ $s=student('Document, Hold');EnrollmentEligibility::addHold(['student_number'=>$s['studentId'],'school_year'=>'2026-2027','term'=>'1st Semester','kind'=>'DOCUMENT','reason'=>'Submit original transcript','office'=>'Admission']);$id=(int)Db::val('SELECT MAX(id) FROM sis_eligibility_holds');expect(!checkStudent($s,'1st Semester',[],null,'Admin reason')['can_create'],'Document hold bypassed');expect(checkStudent($s,'2nd Semester')['can_create'],'Hold leaked into another term');EnrollmentEligibility::releaseHold($id,'Original verified');expect(checkStudent($s)['can_create'],'Released hold still active'); });
scenario('expired holds ignored; expiry on today remains active',function(){ $s=student('Expiry, Hold');$data=['student_number'=>$s['studentId'],'kind'=>'OTHER','reason'=>'Time-limited hold','office'=>'Registrar','expires_on'=>date('Y-m-d',strtotime('-1 day')),'created_by'=>Auth::id()];$id=Db::insert('sis_eligibility_holds',$data);expect(checkStudent($s)['can_create'],'Expired hold applied');Db::update('sis_eligibility_holds',['expires_on'=>date('Y-m-d')],$id);expect(!checkStudent($s)['can_create'],'Inclusive expiry failed'); });
scenario('admission staff cannot manage holds or prerequisite mappings',function()use($admissionUser,$pre,$dependent){$s=student('Permission, Check');Auth::actAs($admissionUser);rejects(fn()=>EnrollmentEligibility::addHold(['student_number'=>$s['studentId']]),'permission');rejects(fn()=>EnrollmentEligibility::savePrerequisite($dependent,$pre),'permission');admin();});
scenario('prerequisite mappings reject direct and indirect cycles',function()use($pre,$dependent,$third){admin();EnrollmentEligibility::savePrerequisite($dependent,$pre);EnrollmentEligibility::savePrerequisite($third,$dependent);rejects(fn()=>EnrollmentEligibility::savePrerequisite($pre,$third),'circular');rejects(fn()=>EnrollmentEligibility::savePrerequisite($pre,$pre),'different');});
scenario('unpassed prerequisite blocks only its subject and permits an editable draft',function()use($pre,$dependent){$s=student('Prerequisite, Missing');$r=checkStudent($s,'1st Semester',[$pre,$dependent]);expect(!$r['can_confirm']&&$r['can_create'],'Subject scope incorrect');expect($r['blocked_subjects']===[$dependent],'Wrong blocked subject');expect(checkStudent($s,'1st Semester',[$pre])['can_confirm'],'Eligible subject blocked');});
scenario('only earlier finalized Passed grades satisfy prerequisites',function()use($dependent){$s=student('Prerequisite, Passed');$grade=['subjectCode'=>'E101','finalGrade'=>1.5,'mark'=>null,'remarks'=>'Passed'];tag($s,'2026-2027','2nd Semester',[$grade]);expect(!checkStudent($s,'1st Semester',[$dependent])['can_confirm'],'Future pass accepted');tag($s,'2025-2026','2nd Semester',[array_replace($grade,['mark'=>'INC'])]);expect(!checkStudent($s,'1st Semester',[$dependent])['can_confirm'],'INC accepted');tag($s,'2025-2026','2nd Semester',[$grade]);expect(checkStudent($s,'1st Semester',[$dependent])['can_confirm'],'Earlier pass rejected');});
scenario('missing subject records fail closed',function(){ $s=student('Missing, Subject');expect(!checkStudent($s,'1st Semester',['not-a-subject'])['can_confirm'],'Missing subject accepted'); });
scenario('INC warning policy can be changed to a hard enrollment block',function()use($section,$fee,$pre){$s=student('Incomplete, Policy');[$rid]=Registration::create(null,$s['studentId'],$section,'1st Semester',$fee,[$pre]);tag($s,'2026-2027','1st Semester',[['subjectCode'=>'E101','finalGrade'=>null,'mark'=>'INC','remarks'=>'Incomplete']]);policy(['eligibility_block_incomplete'=>'0']);expect(checkStudent($s,'2nd Semester')['can_create'],'Warning policy blocked');policy(['eligibility_block_incomplete'=>'1']);expect(!checkStudent($s,'2nd Semester',[],null,'Admin reason')['can_create'],'Hard INC policy bypassed');policy(['eligibility_block_incomplete'=>'0']);});
scenario('confirmation rejects a hold added after a passing preview; rollback preserves draft',function()use($section,$fee,$pre){$s=student('Stale, Preview');[$rid]=Registration::create(null,$s['studentId'],$section,'1st Semester',$fee,[$pre]);expect(EnrollmentEligibility::forRegistration(Registration::get($rid))['can_confirm'],'Initial preview failed');EnrollmentEligibility::addHold(['student_number'=>$s['studentId'],'kind'=>'OTHER','reason'=>'New registrar hold','office'=>'Registrar']);rejects(fn()=>Registration::finish($rid,true),'New registrar hold');expect(Registration::state(Registration::get($rid))==='OPEN','Rejected confirmation locked draft');expect(!Db::val("SELECT 1 FROM sis_journal WHERE registration_id = ?",[$rid]),'Rejected confirmation posted journal');});
scenario('confirmation rechecks selected subjects and writes the final decision',function()use($section,$fee,$pre,$dependent){$s=student('Subject, Confirmation');[$rid]=Registration::create(null,$s['studentId'],$section,'1st Semester',$fee,[$dependent]);rejects(fn()=>Registration::finish($rid,true),'requires a completed passing grade');Registration::update($rid,$fee,[$pre]);Registration::finish($rid,true);expect(Registration::state(Registration::get($rid))==='DONE','Eligible draft not confirmed');$snapshot=json_decode(Db::val("SELECT snapshot FROM sis_eligibility_decisions WHERE registration_id = ? AND stage='CONFIRMED'",[$rid]),true);expect($snapshot['result']==='ELIGIBLE'&&$snapshot['subject_ids']===[$pre],'Wrong saved decision');});
scenario('calendar changes are enforced again and explicit exceptions are scoped',function()use($section,$fee,$pre){$s=student('Calendar, Change');[$rid]=Registration::create(null,$s['studentId'],$section,'Summer',$fee,[$pre]);TermCalendar::save(null,['school_year'=>'2026-2027','term'=>'Summer','enrollment_start'=>date('Y-m-d',strtotime('-2 days')),'enrollment_end'=>date('Y-m-d',strtotime('-1 day'))]);rejects(fn()=>Registration::finish($rid,true),'Enrollment for');Registration::finish($rid,true,'Approved late enrollment by registrar');expect(Registration::state(Registration::get($rid))==='DONE','Explicit calendar exception failed');TermCalendar::delete((int)TermCalendar::get('2026-2027','Summer')['id']);});
scenario('non-admin cannot submit a confirmation exception',function()use($registrar,$section,$fee,$pre){$s=student('Exception, Permission');[$rid]=Registration::create(null,$s['studentId'],$section,'1st Semester',$fee,[$pre]);Auth::actAs($registrar);rejects(fn()=>Registration::finish($rid,true,'Override'),'Only an administrator');admin();});
scenario('balance approvals, minimum payment, voids and revocation are checked',function()use($section,$fee,$pre){$s=student('Balance, Checks');[$old]=Registration::create(null,$s['studentId'],$section,'1st Semester',$fee,[$pre]);tag($s,'2026-2027','1st Semester',[]);policy(['balance_enrollment_enabled'=>'1','balance_min_payment'=>'200.00']);$r=checkStudent($s,'2nd Semester');expect($r['result']==='NEEDS_APPROVAL','Missing approval not detected');$case=BalanceEnrollment::request($s['studentId'],'2026-2027','2nd Semester','ARRANGEMENT',20000,'Installment request');BalanceEnrollment::decide($case,'APPROVED','Approved subject to payment');expect(!checkStudent($s,'2nd Semester',[],null,'Admin reason')['can_create'],'Payment condition bypassed');$payment=Cashier::pay($old,20000,'CASH',null,bin2hex(random_bytes(16)),null);expect(checkStudent($s,'2nd Semester')['can_create'],'Posted payment not counted');[$current]=Registration::create(null,$s['studentId'],$section,'2nd Semester',$fee,[$pre]);Cashier::void((int)$payment['id'],'Reversed test receipt');rejects(fn()=>Registration::finish($current,true),'Posted, non-voided payments');BalanceEnrollment::decide($case,'REJECTED','Approval revoked');expect(checkStudent($s,'2nd Semester',[$pre],$current)['result']==='NEEDS_APPROVAL','Revoked approval reused');policy(['balance_enrollment_enabled'=>'0','balance_min_payment'=>'0.00']);});
scenario('final checker does not require paying the new term balance',function()use($section,$fee,$pre){$s=student('Current, Balance');[$rid]=Registration::create(null,$s['studentId'],$section,'1st Semester',$fee,[$pre]);Registration::finish($rid,true);expect(Registration::balance(Registration::get($rid))>0,'Expected unpaid current balance');});
scenario('migration is repeatable and checks history survives',function(){sis_upgrade();sis_upgrade();expect((int)Db::val('SELECT COUNT(*) FROM sis_eligibility_decisions')>0,'Decision history missing');});
echo "$passed passed, $failures failed\n";
exit($failures ? 1 : 0);
